describe('User Login with Valid Credentials', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should successfully log in with valid credentials and redirect to dashboard', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Fill login form with valid credentials
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('ValidPassword123!');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for API response
    cy.wait('@loginRequest');

    // Verify success message appears
    cy.get('[data-testid="login-success-message"]').should('be.visible').should('contain', 'Login successful');

    // Verify dashboard is visible
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="dashboard-header"]').should('be.visible');

    // Verify user is logged in
    cy.get('[data-testid="user-name"]').should('contain', 'User');
    cy.get('[data-testid="user-email"]').should('contain', 'user@example.com');
  });

  it('should display error message when login fails due to invalid credentials', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 401,
      body: { error: 'Invalid credentials' }
    }).as('loginRequest');

    // Fill login form with invalid credentials
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="password-input"]').type('WrongPassword');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for API response
    cy.wait('@loginRequest');

    // Verify error message appears
    cy.get('[data-testid="login-error-message"]').should('be.visible').should('contain', 'Invalid username or password');

    // Verify login form is still visible
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');

    // Verify user is not logged in
    cy.get('[data-testid="user-name"]').should('not.exist');
  });
});
